/**
 * A reusable hook that encapsulates the state and behaviour required to edit a
 * piece of text inline (for example an entity name).
 *
 * @param isEditing    Whether the field is currently in the editing state.
 * @param name         The current committed value of the text.
 * @param exitEditing  Called when the editing session should end.
 * @param validateName Validates a candidate value, returning an error message
 *                     when invalid or `null` when valid.
 * @param onNameSave   Called with the new value when a valid change is saved.
 *
 * @returns A tuple of
 *  `[inputRef, editableName, validationError, handleKeyUp, handleTitleChange]`.
 */
export function useEditableText(
  isEditing: boolean,
  name: string,
  exitEditing: () => void,
  validateName: (name: string) => string | null,
  onNameSave: (name: string) => void,
): [
  React.RefObject<HTMLInputElement>,
  string,
  string | null,
  (e: React.KeyboardEvent<HTMLInputElement>) => void,
  (e: React.ChangeEvent<HTMLInputElement>) => void,
] {
  const previousName = usePrevious(name);
  const [editableName, setEditableName] = useState(name);
  const [validationError, setValidationError] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const exitWithoutSaving = useCallback(() => {
    exitEditing();
    setEditableName(name);
    setValidationError(null);
  }, [exitEditing, name]);

  const validate = useCallback(
    (value: string) => {
      const nameError = validateName(value);

      setValidationError(nameError);

      return nameError;
    },
    [validateName],
  );

  const attemptSave = useCallback(() => {
    const nameError = validate(editableName);

    if (editableName === name) {
      // No change detected
      exitWithoutSaving();
    } else if (nameError === null) {
      // Save the new name
      onNameSave(editableName);
      exitEditing();
    } else {
      // Exit edit mode and revert name
      exitWithoutSaving();
    }
  }, [editableName, exitEditing, exitWithoutSaving, name, onNameSave, validate]);

  const handleKeyUp = useEventCallback(
    (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (e.key === "Enter") {
        attemptSave();
      } else if (e.key === "Escape") {
        exitWithoutSaving();
      }
    },
  );

  const handleTitleChange = useEventCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const value = e.target.value;

      setEditableName(value);
      validate(value);
    },
  );

  useEventListener(
    "focusout",
    function handleFocusOut() {
      const input = inputRef.current;

      if (input) {
        attemptSave();
      }
    },
    inputRef,
  );

  useEffect(
    function syncEditableTitle() {
      if (!isEditing && previousName !== name) {
        setEditableName(name);
      }
    },
    [name, previousName, isEditing],
  );

  // TODO: This is a temporary fix to focus the input after context retention applies focus to its target
  // this is a nasty hack to re-focus the input after context retention applies focus to its target
  // this will be addressed in a future task, likely by a focus retention modification
  useEffect(
    function recaptureFocusInEventOfFocusRetention() {
      const input = inputRef.current;

      if (isEditing && input) {
        setTimeout(() => {
          input.focus();
        }, 200);
      }
    },
    [isEditing],
  );

  return [
    inputRef,
    editableName,
    validationError,
    handleKeyUp,
    handleTitleChange,
  ];
}
